var n=`1235-mangu`;var t=`world-1235`;var a=`DO`;var s=`central-america-caribbean`;var o=4;var r=47;var l={en:`Mangú`,ua:`Мангу`};var d={en:`Mangú is a dish from Dominican Republic featuring plantain, whole cow milk, red onion, white vinegar. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Мангу, страва кухні країни Домініканська Республіка з такими основними складниками: плантан, цільне коров'яче молоко, червона цибуля, білий оцет. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var g=[{en:`Cook the listed ingredients in simmering water for about 23 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 23 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:23,i:[[`plantain`,850,`g`],[`water`,1200,`ml`],[`table-salt`,8,`g`]]},{en:`Drain the cooked ingredients and pound or mash while warm for about 10 minutes until thick, elastic and smooth; shape into portions with wet hands or a spoon.`,ua:`Злийте воду з готових продуктів і протягом приблизно 10 хвилин товчіть або розминайте теплими до густої гладкої еластичної маси; сформуйте порції вологими руками чи ложкою.`,t:[`mashing`,`pounding`],m:10,i:[[`unsalted-butter`,70,`g`],[`whole-cow-milk`,150,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`red-onion`,210,`g`],[`white-vinegar`,60,`ml`],[`olive-oil`,40,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`queso-fresco`,120,`g`]]}];var h={slug:n,id:t,country:`DO`,region:s,servings:4,minutes:47,title:l,text:d,steps:g};export{a as country,h as default,t as id,r as minutes,s as region,o as servings,n as slug,g as steps,d as text,l as title};